function elecFan(t,s=1,o={}){const sp=o.spin===false?0:t*720;let bl='';for(let i=0;i<3;i++)bl+=`<path d="M0,0C40,-40 40,-140 0,-160C-30,-140 -30,-40 0,0Z" fill="#9FD8F2" stroke="${OL}" stroke-width="5" transform="rotate(${fmt(sp+i*120)})"/>`;
 return g(`scale(${s})`,`<path d="M-20,180L-30,420L30,420L20,180Z" fill="#E9EFF3" stroke="${OL}" stroke-width="7"/><ellipse cx="0" cy="430" rx="150" ry="36" fill="#E9EFF3" stroke="${OL}" stroke-width="7"/><circle r="200" fill="#fff" opacity=".35" stroke="${OL}" stroke-width="8"/>${bl}<circle r="34" fill="#5B6C8F" stroke="${OL}" stroke-width="6"/>`+Array.from({length:8},(_,i)=>`<path d="M0,-200L0,-40" stroke="${OL}" stroke-width="3" opacity=".5" transform="rotate(${i*22.5})"/>`).join('')+(o.wind?Array.from({length:4},(_,i)=>{const ph=(t*1.2+i/4)%1;return `<path d="M${fmt(230+ph*260)},${-90+i*60}q40,-20 80,0" stroke="#fff" stroke-width="10" fill="none" stroke-linecap="round" opacity="${fmt(Math.sin(ph*Math.PI))}"/>`;}).join(''):''));}
function gum(t,s=1,o={}){const bl=o.blob;return g(`scale(${s})`,bl?`<path d="M-90,-20C-100,-80 -20,-100 20,-70C70,-110 120,-40 90,10C120,60 40,100 0,70C-50,100 -120,50 -90,-20Z" fill="#F7A1C4" stroke="${OL}" stroke-width="6"/><ellipse cx="-30" cy="-30" rx="20" ry="12" fill="#fff" opacity=".6"/>${o.face!==false?`<circle cx="-24" cy="10" r="8" fill="#2E2430"/><circle cx="24" cy="10" r="8" fill="#2E2430"/><path d="M-12,34Q0,44 12,34" stroke="#2E2430" stroke-width="5" fill="none"/>`:''}`:`<rect x="-150" y="-50" width="300" height="100" rx="14" fill="#F7A1C4" stroke="${OL}" stroke-width="7"/><rect x="-150" y="-50" width="90" height="100" rx="14" fill="#5DB7EA" stroke="${OL}" stroke-width="7"/><text x="40" y="18" text-anchor="middle" font-family="B2" font-weight="800" font-size="46" fill="#fff">GUM</text>`);}
function gut(t,s=1,o={}){const d="M-320,-160C-120,-260 120,-60 320,-160C420,-200 420,-60 320,-20C120,60 -120,-120 -320,-20C-420,20 -420,160 -320,140C-120,100 120,260 320,160";const w=o.w||90;let s2=`<path d="${d}" stroke="#E9A58C" stroke-width="${w}" fill="none" stroke-linecap="round"/><path d="${d}" stroke="#F3C1AE" stroke-width="${w*0.45}" fill="none" stroke-linecap="round" opacity=".7"/>`;
 if(o.ball!=null){const p=document.createElementNS('http://www.w3.org/2000/svg','path');p.setAttribute('d',d);const L=p.getTotalLength();const pt=p.getPointAtLength(clamp(o.ball)*L);s2+=`<g transform="translate(${fmt(pt.x)},${fmt(pt.y)})">${o.ballSvg||gum(t,0.4,{blob:true,face:false})}</g>`;}
 return g(`scale(${s})`,s2);}
