function thermo(t,s=1,lvl=0.8){const h=260*clamp(lvl);return g(`scale(${s})`,`<rect x="-36" y="-200" width="72" height="300" rx="36" fill="#fff" stroke="${OL}" stroke-width="7"/><rect x="-16" y="${fmt(80-h)}" width="32" height="${fmt(h)}" fill="#E5383B"/><circle cy="120" r="62" fill="#E5383B" stroke="${OL}" stroke-width="7"/>`);}
