function razor(s=1){return g(`scale(${s})`,`<rect x="-20" y="-20" width="40" height="300" rx="20" fill="#5DB7EA" stroke="${OL}" stroke-width="7"/><rect x="-110" y="-80" width="220" height="70" rx="16" fill="#E9EFF3" stroke="${OL}" stroke-width="7"/><path d="M-100,-20L100,-20" stroke="#9AA9B8" stroke-width="8"/>`);}
function hairs(t,s=1,cut=0){let h='';for(let i=0;i<7;i++){const x=-180+i*60;const len=cut?60:220;h+=`<path d="M${x},0L${x},-30" stroke="#5B3A2A" stroke-width="16"/><path d="M${x},-30Q${x+(cut?0:10)},${-30-len/2} ${x+(cut?0:-6)},${-30-len}" stroke="#2E2430" stroke-width="${cut?18:14}" fill="none" stroke-linecap="${cut?'butt':'round'}"/>`;}
 return g(`scale(${s})`,`<rect x="-240" y="0" width="480" height="140" fill="#F3C9A8" stroke="${OL}" stroke-width="7"/><path d="M-240,0L240,0" stroke="#D9A98A" stroke-width="6"/>`+h+Array.from({length:7},(_,i)=>`<ellipse cx="${-180+i*60}" cy="40" rx="18" ry="26" fill="#E8A58C" stroke="${OL}" stroke-width="4"/>`).join(''));}
