function glassW(t,s=1,lvl=0.7){const top=160-320*lvl;return g(`scale(${s})`,`<clipPath id="gw${Math.round(s*100)}"><path d="M-110,-170L110,-170L90,170L-90,170Z"/></clipPath><g clip-path="url(#gw${Math.round(s*100)})"><rect x="-120" y="${fmt(top)}" width="240" height="400" fill="#5DB7EA" opacity=".8"/></g><path d="M-110,-170L110,-170L90,170L-90,170Z" fill="#fff" fill-opacity=".25" stroke="${OL}" stroke-width="7" stroke-linejoin="round"/><path d="M-70,-130L-60,120" stroke="#fff" stroke-width="10" opacity=".6"/>`);}
function radar(t,s=1){const a=t*120;return g(`scale(${s})`,`<circle r="160" fill="#14301F" stroke="#3BB273" stroke-width="8"/><circle r="100" fill="none" stroke="#3BB273" stroke-width="4" opacity=".6"/><circle r="50" fill="none" stroke="#3BB273" stroke-width="4" opacity=".6"/><path d="M0,0L0,-160" stroke="#7BC96F" stroke-width="8" transform="rotate(${fmt(a)})"/><circle cx="60" cy="-70" r="12" fill="#E5383B" opacity="${fmt(0.5+0.5*Math.sin(t*5))}"/>`);}
